-- Generated explicit legacy-clock protocol by author_legacy_clock_copy.py.
-- validation_wall_offset is ONLY a zero-shift wall-value validator when unresolved.
-- It is never persisted as a source offset or used to manufacture UTC.
SET @compact_source_clock_unresolved=BINARY '__SOURCE_MCP_OFFSET__'=BINARY 'UNRESOLVED';
SET @compact_validation_wall_offset=IF(@compact_source_clock_unresolved,'+00:00','__SOURCE_MCP_OFFSET__');
SET NAMES utf8mb4;
SET @compact_mcp_previous_concat=@@SESSION.group_concat_max_len;
SET SESSION group_concat_max_len=3200000;
CREATE TEMPORARY TABLE compact_mcp_guard(valid INT NOT NULL CHECK(valid=1)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_mcp_columns(table_name VARCHAR(64),column_name VARCHAR(64),position_no INT,column_type VARCHAR(64),nullable VARCHAR(3),collation_name VARCHAR(64),default_value VARCHAR(64),extra VARCHAR(64),PRIMARY KEY(table_name,column_name)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_mcp_keys(table_name VARCHAR(64),non_unique INT,is_primary INT,key_columns VARCHAR(1024)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE compact_mcp_sequences AS SELECT table_name,auto_increment FROM information_schema.tables WHERE table_schema='__SOURCE_SCHEMA__' AND table_name IN ('agent_local_mcp','agent_local_mcp_audit','agent_mcp_install_job','agent_mcp_execution','agent_mcp_execution_command','agent_fetch_installation','agent_fetch_lifecycle_command','agent_mcp_install_worker','agent_fetch_image','agent_fetch_image_command','agent_fetch_image_retention','agent_fetch_image_retention_control','agent_fetch_image_retention_event');
SET @compact_mcp_connector_sequence=(SELECT auto_increment FROM compact_mcp_sequences WHERE table_name='agent_local_mcp');
SET @compact_mcp_connector_ddl=CONCAT('ALTER TABLE agent_connector AUTO_INCREMENT=',@compact_mcp_connector_sequence);
PREPARE compact_mcp_connector_statement FROM @compact_mcp_connector_ddl;
EXECUTE compact_mcp_connector_statement;
DEALLOCATE PREPARE compact_mcp_connector_statement;
START TRANSACTION;
CREATE TEMPORARY TABLE compact_mcp_snapshots(source_table VARCHAR(64) PRIMARY KEY,row_count BIGINT NOT NULL,snapshot_sha256 CHAR(64) NOT NULL,bytes_count BIGINT NOT NULL) ENGINE=InnoDB;
SET @compact_mcp_imported_at=UTC_TIMESTAMP(6);
COMMIT;
SET SESSION group_concat_max_len=@compact_mcp_previous_concat;
